 sub=get(f'https://data.sec.gov/submissions/CIK{cik}.json'); facts=get(f'https://data.sec.gov/api/xbrl/companyfacts/CIK{cik}.json'); rec=sub.get('filings',{}).get('recent',{}); dates=rec.get('filingDate',[]); forms=rec.get('form',[]); acc=rec.get('accessionNumber',[])
 recent=[{'form':forms[i] if i<len(forms) else None,'filing_date':dates[i] if i<len(dates) else None,'accession':acc[i] if i<len(acc) else None} for i in range(max(len(forms),len(dates),len(acc)))]
