 return {'cik':cik,'submission_name':sub.get('name'),'tickers':sub.get('tickers',[]),'exchanges':sub.get('exchanges',[]),'former_names':sub.get('formerNames',[]),'recent_filings':recent[:40],'companyfacts_entity_name':facts.get('entityName'),'companyfacts_first_filed':min(fd) if fd else None,'companyfacts_last_filed':max(fd) if fd else None,'companyfacts_filed_count':len(fd)}
